options.queryReplacement:
={{
  [
    String(
      $json.message
      ?? $json.error?.message
      ?? $json.error
      ?? 'unknown embedding error'
    ).slice(0, 4000),

    $('Loop Over Items').item.json.ChunkUUID,

    $('Loop Over Items').item.json.ClaimToken
  ]
}}

parameters.jsCode:
const embedding = $json.embedding;

if (!Array.isArray(embedding)) {
  throw new Error('Ollama response contains no embedding array');
}

if (embedding.length !== 768) {
  throw new Error(
    `Unexpected embedding dimension: ${embedding.length}; expected 768`
  );
}

if (!embedding.every(Number.isFinite)) {
  throw new Error('Embedding contains non-finite values');
}

return [{
  json: {
    embedding,
  },
}];

